-- A product may occur in several searches, with a different image in each.
CREATE TABLE clothes_listing_details (
    item_id TEXT NOT NULL REFERENCES clothes_image_database(item_id) ON DELETE CASCADE,
    search_group TEXT NOT NULL,
    search_term TEXT NOT NULL,
    image_url TEXT NOT NULL,
    ocr_image TEXT NOT NULL,
    discount_pct NUMERIC,
    rating NUMERIC,
    sold_count INTEGER,
    location TEXT,
    is_mall INTEGER NOT NULL CHECK (is_mall IN (0, 1)),
    original_price NUMERIC,
    rating_count INTEGER,
    PRIMARY KEY (item_id, search_term, search_group)
);

CREATE VIEW clothes_catalog AS
SELECT d.search_group, d.search_term, p.shop_id, p.item_id, p.name, p.url, d.image_url,
       p.price, d.discount_pct, d.rating, d.sold_count, d.location, d.is_mall,
       p.currency, d.original_price, d.rating_count, d.ocr_image
FROM clothes_listing_details d JOIN clothes_image_database p ON p.item_id = d.item_id;

-- A row with no product records a completed closet-only look.
CREATE TABLE outfit_enhancements (
    user_id BIGINT NOT NULL,
    option_id BIGINT NOT NULL,
    selection TEXT NOT NULL,
    item_id TEXT REFERENCES clothes_image_database(item_id),
    PRIMARY KEY (user_id, option_id, selection),
    FOREIGN KEY (user_id, option_id) REFERENCES outfit_options(user_id, id) ON DELETE CASCADE
);






